use pulldown_cmark::{Event, HeadingLevel, MetadataBlockKind, Tag, TagEnd};
use pulldown_cmark_to_cmark::cmark_with_options;

use crate::model::config::MarkdownOptions;
use crate::model::node::ColumnAlignment;
use crate::model::{
    document,
    graph::{inlines_to_markdown, GraphBlock, GraphInline, GraphInlines},
    is_ref_url,
};

pub struct MarkdownWriter {
    options: MarkdownOptions,
}

impl MarkdownWriter {
    pub fn new(options: MarkdownOptions) -> MarkdownWriter {
        MarkdownWriter { options }
    }

    pub fn write(&self, blocks: Vec<GraphBlock>) -> String {
        if self.options.bare_frontmatter {
            // Partition: extract leading Frontmatter block, keep rest.
            let mut frontmatter: Option<String> = None;
            let mut rest_blocks = Vec::new();
            let mut seen_first = false;
            for block in blocks {
                if !seen_first {
                    if let GraphBlock::Frontmatter(content) = &block {
                        frontmatter = Some(content.clone());
                        seen_first = true;
                        continue;
                    }
                }
                seen_first = true;
                rest_blocks.push(block);
            }
            let mut buf = String::new();
            if let Some(fm) = frontmatter {
                buf.push_str(fm.trim_end());
                buf.push_str("\n\n");
            }
            let mut body = String::new();
            cmark_with_options(
                self.blocks_events(rest_blocks).iter().cloned(),
                &mut body,
                self.options.formatting.to_cmark_options(),
            )
            .unwrap();
            buf.push_str(&body);
            buf
        } else {
            let mut buf = String::new();
            cmark_with_options(
                self.blocks_events(blocks).iter().cloned(),
                &mut buf,
                self.options.formatting.to_cmark_options(),
            )
            .unwrap();
            buf
        }
    }

    fn blocks_events(&self, iter: Vec<GraphBlock>) -> Vec<Event<'_>> {
        iter.into_iter()
            .flat_map(|block| self.block_events(block))
